import type { CodeFile } from "@/app/types";

/** Served from `public/vendor/pglite/` (generated by `bun run vendor:pglite`). */
export const SQL_WORKER_URL = "/vendor/pglite/sql-worker.js";

/** Rows kept per SELECT, and statements reported per run. The rest is cut so a runaway query cannot flood the page. */
export const SQL_MAX_ROWS = 100;
export const SQL_MAX_STATEMENTS = 100;
export const SQL_MAX_CELL_LENGTH = 200;
/** Time allowed for the statements after the database is ready. The first run also loads PGlite, which is not counted. */
export const SQL_RUN_TIMEOUT_MS = 10_000;
export const SQL_LOAD_TIMEOUT_MS = 60_000;

export type SqlStatementResult =
  | { kind: "rows"; fields: string[]; rows: unknown[][]; totalRows: number }
  | { kind: "command"; command: string; affectedRows: number }
  | { kind: "error"; message: string };

export type SqlWorkerMessage =
  | { type: "ready" }
  | { type: "statement"; index: number; result: SqlStatementResult }
  | { type: "done" }
  | { type: "fatal"; message: string };

/**
 * Splits a script into statements the way psql would for plain scripts: semicolons end a statement
 * unless they sit in a string, a quoted identifier, a comment or a dollar-quoted body. Each statement
 * runs on its own so an error does not hide the results around it (the exercises end with statements
 * that are meant to fail).
 */
export function splitSqlStatements(script: string): string[] {
  const statements: string[] = [];
  let start = 0;
  let i = 0;
  const flush = (end: number) => {
    const text = script.slice(start, end).trim();
    if (hasExecutableText(text)) {
      statements.push(text);
    }
    start = end + 1;
  };
  while (i < script.length) {
    const ch = script[i];
    const next = script[i + 1];
    if (ch === "'" || ch === '"') {
      i = skipQuoted(script, i, ch);
    } else if (ch === "-" && next === "-") {
      const newline = script.indexOf("\n", i);
      i = newline === -1 ? script.length : newline;
    } else if (ch === "/" && next === "*") {
      i = skipBlockComment(script, i);
    } else if (ch === "$") {
      const tag = /^\$[A-Za-z_\u0080-￿]*[A-Za-z0-9_\u0080-￿]*\$/.exec(script.slice(i, i + 64));
      const previous = i > 0 ? script[i - 1] : "";
      // "$1" style parameters and identifiers like a$b$ are not dollar quotes.
      if (tag && !/[A-Za-z0-9_\u0080-￿]/.test(previous) && !/^\$\d/.test(tag[0])) {
        const close = script.indexOf(tag[0], i + tag[0].length);
        i = close === -1 ? script.length : close + tag[0].length;
      } else {
        i++;
      }
    } else if (ch === ";") {
      flush(i);
      i++;
    } else {
      i++;
    }
  }
  flush(script.length);
  return statements;
}

function skipQuoted(script: string, from: number, quote: string): number {
  let i = from + 1;
  while (i < script.length) {
    if (script[i] === quote) {
      if (script[i + 1] === quote) {
        i += 2;
        continue;
      }
      return i + 1;
    }
    i++;
  }
  return script.length;
}

// PostgreSQL block comments nest.
function skipBlockComment(script: string, from: number): number {
  let depth = 0;
  let i = from;
  while (i < script.length) {
    if (script[i] === "/" && script[i + 1] === "*") {
      depth++;
      i += 2;
    } else if (script[i] === "*" && script[i + 1] === "/") {
      depth--;
      i += 2;
      if (depth === 0) {
        return i;
      }
    } else {
      i++;
    }
  }
  return script.length;
}

/** A chunk of only comments and whitespace is not a statement (PGlite would reject the empty query). */
function hasExecutableText(text: string): boolean {
  let i = 0;
  while (i < text.length) {
    const ch = text[i];
    if (/\s/.test(ch)) {
      i++;
    } else if (ch === "-" && text[i + 1] === "-") {
      const newline = text.indexOf("\n", i);
      i = newline === -1 ? text.length : newline;
    } else if (ch === "/" && text[i + 1] === "*") {
      i = skipBlockComment(text, i);
    } else {
      return true;
    }
  }
  return false;
}

/** The text to run: files in the order the exercise lists them. */
export function buildSqlScript(files: readonly Pick<CodeFile, "content">[]): string {
  return files.map((file) => file.content).join("\n");
}

/** Cell text for the result table. Always a string, so the table renders it as text, never as HTML. */
export function formatSqlCell(value: unknown): string {
  let text: string;
  if (value === null || value === undefined) {
    return "NULL";
  }
  if (typeof value === "string") {
    text = value;
  } else if (typeof value === "object") {
    text = value instanceof Date ? value.toISOString() : safeStringify(value);
  } else {
    text = String(value);
  }
  return text.length > SQL_MAX_CELL_LENGTH ? `${text.slice(0, SQL_MAX_CELL_LENGTH)}…` : text;
}

function safeStringify(value: object): string {
  try {
    return JSON.stringify(value, (_key, v) => (typeof v === "bigint" ? v.toString() : v));
  } catch {
    return String(value);
  }
}

/** One-line summary for a statement that returns no rows, like psql's command tag. */
export function formatSqlCommand(command: string, affectedRows: number): string {
  const tag = command.trim().toUpperCase();
  if (tag === "INSERT" || tag === "UPDATE" || tag === "DELETE") {
    return `${tag}（${affectedRows} 行）`;
  }
  return tag === "" ? "実行しました" : `${tag}（実行しました）`;
}

/**
 * The worker is a same-origin file, but a message is still checked before it reaches the page: only
 * the known shapes get through, and a result that is not the expected shape is dropped.
 */
export function acceptSqlWorkerMessage(raw: unknown): SqlWorkerMessage | null {
  const data = raw as Record<string, unknown> | null;
  if (!data || typeof data !== "object") {
    return null;
  }
  switch (data.type) {
    case "ready":
    case "done":
      return { type: data.type };
    case "fatal":
      return typeof data.message === "string" ? { type: "fatal", message: data.message } : null;
    case "statement": {
      const result = parseStatementResult(data.result);
      return typeof data.index === "number" && result
        ? { type: "statement", index: data.index, result }
        : null;
    }
    default:
      return null;
  }
}

function parseStatementResult(raw: unknown): SqlStatementResult | null {
  const result = raw as Record<string, unknown> | null;
  if (!result || typeof result !== "object") {
    return null;
  }
  if (result.kind === "error" && typeof result.message === "string") {
    return { kind: "error", message: result.message };
  }
  if (
    result.kind === "command" &&
    typeof result.command === "string" &&
    typeof result.affectedRows === "number"
  ) {
    return { kind: "command", command: result.command, affectedRows: result.affectedRows };
  }
  if (
    result.kind === "rows" &&
    Array.isArray(result.fields) &&
    result.fields.every((f) => typeof f === "string") &&
    Array.isArray(result.rows) &&
    result.rows.every(Array.isArray) &&
    typeof result.totalRows === "number"
  ) {
    return {
      kind: "rows",
      fields: result.fields as string[],
      rows: result.rows as unknown[][],
      totalRows: result.totalRows,
    };
  }
  return null;
}
